```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

let lines = [];
rl.on('line', line => {
    lines.push(line);
});

rl.on('close', () => {
    const n = parseInt(lines[0]);
    const a = lines[1].trim();

    // For each digit, we need to find the prime factorization of its factorial
    // and then represent it as a product of digits 2-9 that maximize the number

    // The key insight: we want to maximize the number x such that the product of factorials of digits of x equals the product of factorials of digits of a.
    // 
    // Let's think about it differently. We have a multiset of prime factors from the factorials of digits in a.
    // We need to form digits (2-9) from these prime factors such that the resulting number is maximum.
    //
    // To maximize the number, we want:
    // 1. Maximum number of digits (more digits = larger number)
    // 2. Among same length, lexicographically largest (so sort digits in descending order)
    //
    // Each digit 2-9 has a prime factorization:
    // 2 = 2
    // 3 = 3
    // 4 = 2^2
    // 5 = 5
    // 6 = 2*3
    // 7 = 7
    // 8 = 2^3
    // 9 = 3^2
    //
    // We should prefer digits that use fewer prime factors to create more digits.
    // Specifically, we should break down composite digits into their prime factors if it leads to more digits.
    //
    // Actually, the standard approach for this problem is:
    // For each digit d in a, compute d! and factorize it into primes.
    // Then, greedily assign prime factors to digits 9, 8, 7, 6, 5, 4, 3, 2 (in this order) to maximize the number.
    // Wait, that's not quite right. Let me think again.
    //
    // The correct approach:
    // 1. Compute the total prime factorization of the product of factorials of all digits in a.
    // 2. Then, we want to form the largest possible number using digits 2-9.
    // 3. To do this, we should use as many 9s as possible (since 9 = 3^2, it uses two 3s), then 8s (8 = 2^3), then 7s, then 6s (6 = 2*3), then 5s, then 4s (4 = 2^2), then 3s, then 2s.
    // Wait, but we want the maximum number. So we want the digits sorted in descending order.
    // The key is to maximize the count of digits first, then the lexicographic order.
    //
    // Actually, the standard solution is:
    // - For each digit in a, factorize its factorial.
    // - Count the total number of each prime factor (2, 3, 5, 7).
    // - Then, greedily form digits from 9 down to 2:
    //   - 9: use 3^2, so count how many 9s we can form
    //   - 8: use 2^3
    //   - 7: use 7
    //   - 6: use 2*3
    //   - 5: use 5
    //   - 4: use 2^2
    //   - 3: use 3
    //   - 2: use 2
    // - Sort the resulting digits in descending order and output.

    // Factorize factorials of digits 0-9
    // 0! = 1, 1! = 1, 2! = 2, 3! = 6, 4! = 24, 5! = 120, 6! = 720, 7! = 5040, 8! = 40320, 9! = 362880

    // Prime factors for each digit's factorial:
    // 0: {}
    // 1: {}
    // 2: {2:1}
    // 3: {2:1, 3:1}
    // 4: {2:3, 3:1}  (4! = 24 = 2^3 * 3)
    // 5: {2:3, 3:1, 5:1}  (5! = 120 = 2^3 * 3 * 5)
    // 6: {2:4, 3:2, 5:1}  (6! = 720 = 2^4 * 3^2 * 5)
    // 7: {2:4, 3:2, 5:1, 7:1}  (7! = 5040 = 2^4 * 3^2 * 5 * 7)
    // 8: {2:7, 3:2, 5:1, 7:1}  (8! = 40320 = 2^7 * 3^2 * 5 * 7)
    // 9: {2:7, 3:4, 5:1, 7:1}  (9! = 362880 = 2^7 * 3^4 * 5 * 7)

    const factorialFactors = [
        {},
        {},
        {2: 1},
        {2: 1, 3: 1},
        {2: 3, 3: 1},
        {2: 3, 3: 1, 5: 1},
        {2: 4, 3: 2, 5: 1},
        {2: 4, 3: 2, 5: 1, 7: 1},
        {2: 7, 3: 2, 5: 1, 7: 1},
        {2: 7, 3: 4, 5: 1, 7: 1}
    ];

    // Count total prime factors
    let count2 = 0, count3 = 0, count5 = 0, count7 = 0;

    for (let i = 0; i < n; i++) {
        const d = parseInt(a[i]);
        const factors = factorialFactors[d];
        if (factors[2]) count2 += factors[2];
        if (factors[3]) count3 += factors[3];
        if (factors[5]) count5 += factors[5];
        if (factors[7]) count7 += factors[7];
    }

    // Now form digits from 9 down to 2
    let digits = [];

    // 9 = 3^2
    let num9 = Math.floor(count3 / 2);
    count3 -= num9 * 2;
    for (let i = 0; i < num9; i++) digits.push(9);

    // 8 = 2^3
    let num8 = Math.floor(count2 / 3);
    count2 -= num8 * 3;
    for (let i = 0; i < num8; i++) digits.push(8);

    // 7 = 7
    let num7 = count7;
    count7 -= num7;
    for (let i = 0; i < num7; i++) digits.push(7);

    // 6 = 2 * 3
    let num6 = Math.min(count2, count3);
    count2 -= num6;
    count3 -= num6;
    for (let i = 0; i < num6; i++) digits.push(6);

    // 5 = 5
    let num5 = count5;
    count5 -= num5;
    for (let i = 0; i < num5; i++) digits.push(5);

    // 4 = 2^2
    let num4 = Math.floor(count2 / 2);
    count2 -= num4 * 2;
    for (let i = 0; i < num4; i++) digits.push(4);

    // 3 = 3
    let num3 = count3;
    count3 -= num3;
    for (let i = 0; i < num3; i++) digits.push(3);

    // 2 = 2
    let num2 = count2;
    count2 -= num2;
    for (let i = 0; i < num2; i++) digits.push(2);

    // Sort digits in descending order
    digits.sort((a, b) => b - a);

    console.log(digits.join(''));
});
