const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let lines = [];
rl.on('line', (line) => {
    lines.push(line);
});

rl.on('close', () => {
    const n = parseInt(lines[0]);
    const a = lines[1].trim();

    // For each digit, we need to find the optimal decomposition
    // We want to maximize the number x such that product of factorials of digits of x equals product of factorials of digits of a
    // And x should not contain 0 or 1

    // Key insight: we can break down digits into prime factors and then reconstruct
    // Factorials:
    // 0! = 1
    // 1! = 1
    // 2! = 2
    // 3! = 6 = 2*3
    // 4! = 24 = 2^3 * 3
    // 5! = 120 = 2^3 * 3 * 5
    // 6! = 720 = 2^4 * 3^2 * 5
    // 7! = 5040 = 2^4 * 3^2 * 5 * 7
    // 8! = 40320 = 2^7 * 3^2 * 5 * 7
    // 9! = 362880 = 2^7 * 3^4 * 5 * 7

    // We want to express the total product as a product of factorials of digits (2-9)
    // To maximize the number, we want as many digits as possible, and larger digits first

    // Strategy: convert each digit to its prime factorization, sum up all prime factors,
    // then greedily assign digits from 9 down to 2

    // Prime factors for each digit's factorial:
    // digit: {2: count, 3: count, 5: count, 7: count}
    const digitFactors = {
        '0': {2: 0, 3: 0, 5: 0, 7: 0},
        '1': {2: 0, 3: 0, 5: 0, 7: 0},
        '2': {2: 1, 3: 0, 5: 0, 7: 0},
        '3': {2: 1, 3: 1, 5: 0, 7: 0},
        '4': {2: 3, 3: 1, 5: 0, 7: 0},
        '5': {2: 3, 3: 1, 5: 1, 7: 0},
        '6': {2: 4, 3: 2, 5: 1, 7: 0},
        '7': {2: 4, 3: 2, 5: 1, 7: 1},
        '8': {2: 7, 3: 2, 5: 1, 7: 1},
        '9': {2: 7, 3: 4, 5: 1, 7: 1}
    };

    // Total prime factors
    let total = {2: 0, 3: 0, 5: 0, 7: 0};

    for (let i = 0; i < n; i++) {
        const d = a[i];
        const factors = digitFactors[d];
        total[2] += factors[2];
        total[3] += factors[3];
        total[5] += factors[5];
        total[7] += factors[7];
    }

    // Now greedily assign digits from 9 down to 2
    // For each digit, check if we can use it (i.e., we have enough prime factors)
    // We want to maximize the number, so we use larger digits first

    const result = [];

    for (let d = 9; d >= 2; d--) {
        const factors = digitFactors[d.toString()];
        while (total[2] >= factors[2] && total[3] >= factors[3] && total[5] >= factors[5] && total[7] >= factors[7]) {
            result.push(d.toString());
            total[2] -= factors[2];
            total[3] -= factors[3];
            total[5] -= factors[5];
            total[7] -= factors[7];
        }
    }

    // The result is already in descending order (9,8,7,...,2), which gives the maximum number
    console.log(result.join(''));
