const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let lines = [];
rl.on('line', (line) => {
    lines.push(line);
});

rl.on('close', () => {
    const n = parseInt(lines[0]);
    const a = lines[1].trim();

    // We need to find the maximum number x such that F(x) = F(a)
    // where F(x) is product of factorials of digits of x.
    // x cannot contain 0 or 1.

    // Key insight: We can decompose each digit's factorial into prime factors
    // and then reconstruct the digits of x from those prime factors.
    // The digits that are "prime" in the sense that their factorial cannot be 
    // decomposed into factorials of smaller digits (excluding 0,1) are: 2, 3, 5, 7.
    // Actually, let's think about which digits can be used:
    // 2! = 2
    // 3! = 6 = 3 * 2
    // 4! = 24 = 4 * 3 * 2 = (2^3) * 3
    // 5! = 120 = 5 * 4 * 3 * 2 = (2^3) * 3 * 5
    // 6! = 720 = 6 * 5! = (2^4) * 3^2 * 5
    // 7! = 5040 = 7 * 6! = (2^4) * 3^2 * 5 * 7
    // 8! = 40320 = 8 * 7! = (2^7) * 3^2 * 5 * 7
    // 9! = 362880 = 9 * 8! = (2^7) * 3^4 * 5 * 7

    // To maximize the number, we want the most digits possible, and among those, 
    // the largest digits first.
    // The optimal approach is to convert each digit to its prime factorization,
    // sum up all prime factors, then greedily assign the largest possible digits
    // (7, 5, 3, 2) that can be formed from the remaining prime factors.

    // Prime factorization of d!:
    // 0! = 1
    // 1! = 1
    // 2! = 2
    // 3! = 2 * 3
    // 4! = 2^3 * 3
    // 5! = 2^3 * 3 * 5
    // 6! = 2^4 * 3^2 * 5
    // 7! = 2^4 * 3^2 * 5 * 7
    // 8! = 2^7 * 3^2 * 5 * 7
    // 9! = 2^7 * 3^4 * 5 * 7

    // We'll count the total number of each prime factor (2, 3, 5, 7) across all digits.
    let count2 = 0, count3 = 0, count5 = 0, count7 = 0;

    for (let i = 0; i < n; i++) {
        let d = parseInt(a[i]);
        switch (d) {
            case 0:
            case 1:
                // 0! = 1, 1! = 1, no prime factors
                break;
            case 2:
                count2 += 1;
                break;
            case 3:
                count2 += 1;
                count3 += 1;
                break;
            case 4:
                count2 += 3;
                count3 += 1;
                break;
            case 5:
                count2 += 3;
                count3 += 1;
                count5 += 1;
                break;
            case 6:
                count2 += 4;
                count3 += 2;
                count5 += 1;
                break;
            case 7:
                count2 += 4;
                count3 += 2;
                count5 += 1;
                count7 += 1;
                break;
            case 8:
                count2 += 7;
                count3 += 2;
                count5 += 1;
                count7 += 1;
                break;
            case 9:
                count2 += 7;
                count3 += 4;
                count5 += 1;
                count7 += 1;
                break;
        }
    }

    // Now greedily assign digits 7, 5, 3, 2 (in that order to maximize the number)
    let result = [];

    // Digit 7 requires: 2^4 * 3^2 * 5 * 7
    while (count2 >= 4 && count3 >= 2 && count5 >= 1 && count7 >= 1) {
        result.push('7');
        count2 -= 4;
        count3 -= 2;
        count5 -= 1;
        count7 -= 1;
    }

    // Digit 5 requires: 2^3 * 3 * 5
    while (count2 >= 3 && count3 >= 1 && count5 >= 1) {
        result.push('5');
        count2 -= 3;
        count3 -= 1;
        count5 -= 1;
    }

    // Digit 3 requires: 2 * 3
    while (count2 >= 1 && count3 >= 1) {
        result.push('3');
        count2 -= 1;
        count3 -= 1;
    }

    // Digit 2 requires: 2
    while (count2 >= 1) {
        result.push('2');
        count2 -= 1;
    }

    // Sort the result in descending order to get the maximum number
    result.sort((a, b) => b - a);

    console.log(result.join(''));
});
