    // 6! = 6 * 5 * 4 * 3 * 2 = 2^4 * 3^2 * 5
    // 7! = 7 * 6 * 5 * 4 * 3 * 2 = 2^4 * 3^2 * 5 * 7
    // 8! = 8 * 7 * 6 * 5 * 4 * 3 * 2 = 2^7 * 3^2 * 5 * 7
