    //
    // So the optimal decomposition is:
    // - 9 -> 7,3,3,2
    // - 8 -> 7,2,2,2
    // - 6 -> 5,3
    // - 4 -> 3,2,2
    // - 5, 3, 2, 7 stay as is
    //
    // After this decomposition, we just sort the digits in descending order.

    let digits = [];

    for (let i = 0; i < a.length; i++) {
