            case 2:
                digits.push(2);
                break;
            case 3:
                digits.push(3);
                break;
            case 4:
                digits.push(3, 2, 2);
                break;
            case 5:
                digits.push(5);
                break;
            case 6:
                digits.push(5, 3);
                break;
            case 7:
