                break;
            case 8:
                digits.push(7, 2, 2, 2);
                break;
            case 9:
                digits.push(7, 3, 3, 2);
                break;
        }
    }

    // Sort in descending order
    digits.sort((a, b) => b - a);

    process.stdout.write(digits.join('') + '\n');
